KG42.register("rules-fa9b5e71969d6c2bbfe637d7",{"id":"32-wholesale_prosumer_storage::v141-c-R009","paper":"32-wholesale_prosumer_storage","record":{"rule_id":"v141-c-R009","mechanism_id":"v141-a-M01","name":"Energy-trade execution","process_stage":"activation","market_meaning":"Committing the day-ahead supply bid entails an obligation to fulfill the committed electricity exchange in every possible scenario. Scope: Community day-ahead supply commitments in the modeled wholesale-market arrangement. Condition: When production exceeds demand and the community commits a day-ahead supply bid. STEP automatically procures electricity from the wholesale market based on coordinated community information. Scope: STEP's automatic wholesale electricity procurement for the community. Direct trading with other peers is prohibited. Scope: Direct peer-to-peer electricity trading in the modeled community. Condition: Base case. Direct trading between peers is disabled. Scope: Direct peer-to-peer electricity trading in the modeled community. Condition: BAT market case. Direct P2P electricity trading within the community is permitted. Scope: Direct peer-to-peer electricity trading in the modeled community. Condition: P2P market case. P2P electricity trading within the community is permitted. Scope: Direct peer-to-peer electricity trading in the modeled community. Condition: STEP market case. Grid infeed to the day-ahead market is permitted in all four cases. Scope: Community grid infeed in all four modeled comparison cases. Infeed from the community into the intraday market is prohibited. Scope: Community exports to the wholesale intraday market. Electricity for grid infeed may originate only from distributed generation or a residential battery. Scope: Source restriction on community electricity fed into the grid. Condition: When grid infeed occurs. The community may procure electricity in the intraday market at uncertain reserve prices under this condition. Scope: Second-stage community procurement from the wholesale intraday market. Condition: P2P trade and battery utilisation cannot balance supply and demand. P2P sales and purchases must remain within the community. Scope: Local P2P electricity sales and purchases in the modeled community. Condition: When local P2P trade occurs. Direct P2P trade accounts for the stated transmission and conversion loss of 7.6%. Scope: Modeled direct P2P electricity exchanges. Condition: When direct P2P trade occurs.","independence_rationale":"Relations governed by the approved function execution.energy_trade under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["bidding.supply","coordination.local_operator","execution.energy_trade"],"E":[{"edge_id":"v141-c-R009-E001","source":"bidding.supply","target":"execution.energy_trade","type":"implies","constraint_ids":["v141-c-R009-C001"],"evidence_ids":["v141-b-g03-E03"]},{"edge_id":"v141-c-R009-E002","source":"coordination.local_operator","target":"execution.energy_trade","type":"links","constraint_ids":["v141-c-R009-C002"],"evidence_ids":["v141-b-g02-e08"]}],"omega":{"market_type":"LEM_DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"activation","context_text":"Community day-ahead supply commitments in the modeled wholesale-market arrangement. | Community exports to the wholesale intraday market. | Community grid infeed in all four modeled comparison cases. | Direct peer-to-peer electricity trading in the modeled community. | Local P2P electricity sales and purchases in the modeled community. | Modeled direct P2P electricity exchanges. | STEP's automatic wholesale electricity procurement for the community. | Second-stage community procurement from the wholesale intraday market. | Source restriction on community electricity fed into the grid.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g02-e07","v141-b-g02-e08","v141-b-g02-e10","v141-b-g02-e12","v141-b-g02-e22","v141-b-g02-e24","v141-b-g02-e38","v141-b-g03-E02","v141-b-g03-E03"]},"x":[{"variable_id":"v141-c-R009-x01","symbol":"X^{(t,h,s)}","meaning":"Overall P2P electricity sale of house h in time step t and scenario s, aggregated over peers and used in the community P2P balance Eq. (9).","kind":"operational","domain":"Unspecified in supplied text; P2P electricity sale quantity indexed by t, h, s.","unit":null,"indices":["t","h","s"],"evidence_ids":["v141-b-g02-e19","v141-b-g02-e21","v141-b-g02-e24"]},{"variable_id":"v141-c-R009-x02","symbol":"I^{(t,h,s)}","meaning":"Overall P2P electricity purchase of house h in time step t and scenario s, aggregated over peers and used in the community P2P balance Eq. (9).","kind":"operational","domain":"Unspecified in supplied text; P2P electricity purchase quantity indexed by t, h, s.","unit":null,"indices":["t","h","s"],"evidence_ids":["v141-b-g02-e21","v141-b-g02-e23","v141-b-g02-e24"]}],"theta":[{"parameter_id":"v141-c-R009-theta01","symbol":"\\psi^{P2P}","meaning":"Efficiency factor for conversion and transmission of DG sources to P2P sale in Table 1; the text states that direct P2P trade incurs a transmission and conversion loss of 7.6%, but the supplied material does not explicitly equate psi^P2P to a numeric efficiency coefficient.","value":{"kind":"symbolic","number_value":null,"text_value":"Efficiency factor applied to direct P2P trade; stated loss is 7.6%, but the exact numeric coefficient used in Eq. (9) is not explicitly stated in the supplied text."},"unit":null,"indices":[],"evidence_ids":["v141-b-g02-e21","v141-b-g02-e22"]}],"phi":[{"constraint_id":"v141-c-R009-C001","kind":"logical","role":"core","statement":"Committing the day-ahead supply bid entails an obligation to fulfill the committed electricity exchange in every possible scenario. Scope: Community day-ahead supply commitments in the modeled wholesale-market arrangement. Condition: When production exceeds demand and the community commits a day-ahead supply bid.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.supply","execution.energy_trade"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g03-E03"]},{"constraint_id":"v141-c-R009-C002","kind":"procedural","role":"core","statement":"STEP automatically procures electricity from the wholesale market based on coordinated community information. Scope: STEP's automatic wholesale electricity procurement for the community.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.local_operator","execution.energy_trade"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-e08"]},{"constraint_id":"v141-c-R009-C003","kind":"procedural","role":"core","statement":"Direct trading with other peers is prohibited. Scope: Direct peer-to-peer electricity trading in the modeled community. Condition: Base case.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["execution.energy_trade"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-e38"]},{"constraint_id":"v141-c-R009-C004","kind":"procedural","role":"core","statement":"Direct trading between peers is disabled. Scope: Direct peer-to-peer electricity trading in the modeled community. Condition: BAT market case.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["execution.energy_trade"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-e38"]},{"constraint_id":"v141-c-R009-C005","kind":"procedural","role":"core","statement":"Direct P2P electricity trading within the community is permitted. Scope: Direct peer-to-peer electricity trading in the modeled community. Condition: P2P market case.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["execution.energy_trade"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-e38"]},{"constraint_id":"v141-c-R009-C006","kind":"procedural","role":"core","statement":"P2P electricity trading within the community is permitted. Scope: Direct peer-to-peer electricity trading in the modeled community. Condition: STEP market case.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["execution.energy_trade"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-e38"]},{"constraint_id":"v141-c-R009-C007","kind":"procedural","role":"core","statement":"Grid infeed to the day-ahead market is permitted in all four cases. Scope: Community grid infeed in all four modeled comparison cases.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["execution.energy_trade"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g03-E02"]},{"constraint_id":"v141-c-R009-C008","kind":"procedural","role":"core","statement":"Infeed from the community into the intraday market is prohibited. Scope: Community exports to the wholesale intraday market.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["execution.energy_trade"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-e10"]},{"constraint_id":"v141-c-R009-C009","kind":"procedural","role":"core","statement":"Electricity for grid infeed may originate only from distributed generation or a residential battery. Scope: Source restriction on community electricity fed into the grid. Condition: When grid infeed occurs.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["execution.energy_trade"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-e07"]},{"constraint_id":"v141-c-R009-C010","kind":"procedural","role":"core","statement":"The community may procure electricity in the intraday market at uncertain reserve prices under this condition. Scope: Second-stage community procurement from the wholesale intraday market. Condition: P2P trade and battery utilisation cannot balance supply and demand.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["execution.energy_trade"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-e12"]},{"constraint_id":"v141-c-R009-C011","kind":"mathematical","role":"core","statement":"P2P sales and purchases must remain within the community. Scope: Local P2P electricity sales and purchases in the modeled community. Condition: When local P2P trade occurs.","expression":"\\sum_{h} \\psi^{P2P} X^{(t,h,s)} = \\sum_{h} I^{(t,h,s)} \\quad \\forall t \\in T, s \\in S.","formalization_origin":"source","template_id":null,"members":["execution.energy_trade"],"variable_refs":["v141-c-R009-x01","v141-c-R009-x02"],"parameter_refs":["v141-c-R009-theta01"],"evidence_ids":["v141-b-g02-e24"]},{"constraint_id":"v141-c-R009-C012","kind":"procedural","role":"core","statement":"Direct P2P trade accounts for the stated transmission and conversion loss of 7.6%. Scope: Modeled direct P2P electricity exchanges. Condition: When direct P2P trade occurs.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["execution.energy_trade"],"variable_refs":[],"parameter_refs":["v141-c-R009-theta01"],"evidence_ids":["v141-b-g02-e22"]}],"pi":[{"evidence_id":"v141-b-g02-e07","location":{"location_id":"src-3c39fd6f72-p05-c1r2__v141-a-M01-pricing","page":5,"printed_page":null,"section":null,"anchor_text":"Fig. 2. Flow diagram fo the local market are lower than the grid consumption price (i.e. • the price","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"condition"},"source_text":"The source of electricity for infeed can only be DG or the residential battery, but to promote the local utilisation of distributed energy resources, local markets should consider a price structure with p_F^{(t)} ≤ p_{P2P}^{(t)} ≤ p_{DA\\_G}^{(t)}, i.e. feed price ≤ P2P price ≤ grid price."},{"evidence_id":"v141-b-g02-e08","location":{"location_id":"src-3c39fd6f72-p05-c1r3__v141-a-M01-coordination","page":5,"printed_page":null,"section":null,"anchor_text":"The STEP automatically performs the bidding into the day- ahead market based on the community’s dema","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"The STEP automatically performs the bidding into the day-ahead market based on the community’s demand and day-ahead forecasted generation. The STEP is slightly different from aggregator models (see e.g. [33,34]) as it only coordinates the information flows (i.e. a smart box) in the system and does not assume ownership of the electricity. It then acts automatically based on this information, i.e. it bids to or procures electricity from the wholesale market, and plans the P2P trade and battery utilisation in the community. The STEP is not a service providing agent, but rather a computational interface between the wholesale market and the community which makes automatic decisions based on rules specified by the community members."},{"evidence_id":"v141-b-g02-e10","location":{"location_id":"src-3c39fd6f72-p05-c1r4__v141-a-M01-clearing","page":5,"printed_page":null,"section":null,"anchor_text":"ment from the intraday market to secure supply in every possible eac scenario. Intraday prices are d","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"unknown"},"source_text":"We assume that infeed from the community into the intraday market is not allowed in order to reduce arbitrage potential for the community or single households due to price differences between day-ahead and intraday spot prices. Ultimately, if the day-ahead forecast strongly underestimates the own distributed generation, it may not be storable or usable within the community and must be curtailed."},{"evidence_id":"v141-b-g02-e12","location":{"location_id":"src-3c39fd6f72-p05-c2r3__v141-a-M01-clearing","page":5,"printed_page":null,"section":null,"anchor_text":"- sible generation proﬁles for wind and solar are considered. The d supply-demand balance from the ﬁ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"Second stage: Uncertainty about the production level of distributed generation realises, i.e. different scenarios on the possible generation profiles for wind and solar are considered. The supply-demand balance from the first stage is extended by the deviations in renewable production with the additional possibility of adjusting the day-ahead decisions for battery utilisation and P2P trade. In case of an inability to balance supply and demand with these two market features, the community can procure electricity at uncertain reserve prices in the intraday market."},{"evidence_id":"v141-b-g02-e22","location":{"location_id":"src-3c39fd6f72-p07-c1r1__v141-a-M01-clearing","page":7,"printed_page":null,"section":null,"anchor_text":"168 J.M. Zepter, A. Lüth and P. Crespo del Granado et al. / account a transmission and conversion lo","equation_id":"Eqs. (8)-(9)","figure_id":null,"table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"formula"},"source_text":"The direct trade takes into account a transmission and conversion loss \\psi^{P2P} of 7.6% (see [24])."},{"evidence_id":"v141-b-g02-e24","location":{"location_id":"src-3c39fd6f72-p07-c1r1__v141-a-M01-clearing","page":7,"printed_page":null,"section":null,"anchor_text":"168 J.M. Zepter, A. Lüth and P. Crespo del Granado et al. / account a transmission and conversion lo","equation_id":"Eqs. (8)-(9)","figure_id":null,"table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"formula"},"source_text":"The sold and purchased quantity can, thus, only stay within the community. The sum of sales over all houses needs to equal the purchases as follows: \\sum_{h} \\psi^{P2P} · X^{(t,h,s)} = \\sum_{h} I^{(t,h,s)} \\quad ∀ t ∈ T, s ∈ S. \\qquad (9)"},{"evidence_id":"v141-b-g02-e38","location":{"location_id":"src-3c39fd6f72-p09-c1r3__v141-a-M01-participation","page":9,"printed_page":null,"section":null,"anchor_text":"As of today, electricity end-users are at the end of the supply era chain in a still predominant top","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-09.png","occurrence_role":"definition"},"source_text":"Today’s UK market under dynamic pricing – assuming smart metering – serves in this paper as our base case. To identify the value of each of the proposed local market features – P2P trade and battery storage –, three further cases are compared to the base case: We add P2P trade and battery storage possibilities one by one to investigate their sole values to the system. In short, we apply our model to four cases that distinguish by their options of battery storage and P2P trade. The possibility of feeding from the community into the grid is enabled in all cases. We define the following: • The Base case is defined as today’s electricity market under dynamic real-time pricing. It is not possible to directly trade with other peers, and no electricity storage possibilities are deployed within this case. • The BAT market introduces the possibility of battery storage. Direct trade between the peers is disabled. • The P2P market includes the direct P2P trade connection in the community. The possibility of storage is, however, not implemented. • The STEP market offers both battery storage and P2P trade options within the community."},{"evidence_id":"v141-b-g03-E02","location":{"location_id":"src-3c39fd6f72-p10-c2r4__v141-a-M01-coordination","page":10,"printed_page":null,"section":null,"anchor_text":"5.2. Local markets and wholesale market participation The introduction of local markets intends to p","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-10.png","occurrence_role":"condition"},"source_text":"All four cases we apply allow for the possibility of grid infeed to the day-ahead market at dynamic compensations. The amount fed into the day-ahead market varies significantly between the cases."},{"evidence_id":"v141-b-g03-E03","location":{"location_id":"src-3c39fd6f72-p11-c1r4__v141-a-M01-bidding","page":11,"printed_page":null,"section":null,"anchor_text":"The more local market features we introduce, the higher the proportion of feed and consumption: 89% ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-11.png","occurrence_role":"condition"},"source_text":"Whenever the production exceeds the demand, the community commits a bid to the day-ahead market which they need to fulfil (in all possible scenarios)."},{"evidence_id":"v141-b-g02-e19","location":{"location_id":"src-3c39fd6f72-p06-c2r4__v141-a-M01-clearing","page":6,"printed_page":null,"section":null,"anchor_text":"with their fellow peers. To model these P2P interactions, we ap- ces ply a basic transportation mode","equation_id":"Eqs. (6)-(7)","figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"The community allows prosumers the direct trade of electricity with their fellow peers. To model these P2P interactions, we apply a basic transportation model for the trade of electricity. The following equations hold true for both stages. To this end, the overall quantity sold X^{(t,h,s)} in both stages for each house h ∈ H is defined as the sum of all electricity flows X_{p}^{(t,h→p,s)} from this house h ∈ H to its peers p ∈ H, as specified in Eq. (6). X^{(t,h,s)} = \\sum_{p≠h} X_{p}^{(t,h→p,s)} \\qquad (6)"},{"evidence_id":"v141-b-g02-e21","location":{"location_id":"src-3c39fd6f72-p06-c1r1__v141-a-M01-clearing","page":6,"printed_page":null,"section":null,"anchor_text":"J.M. Zepter, A. Lüth and P. Crespo del Granado et Table 1 Designated sets, parameters and variables ","equation_id":null,"figure_id":null,"table_id":"Table 1","image_ref":"pages/page-06.png","occurrence_role":"definition"},"source_text":"Table 1 Designated sets, parameters and variables of the mathematical model. Sets: t ∈ T hours t in time horizon T; h, p ∈ H houses h and peers p in community H; s ∈ S scenarios s in set of scenarios S. Scalars: \\psi^{P2P} efficiency factor for conversion and transmission of DG sources to P2P sale; \\underline{s}/\\overline{s} upper/lower bounds of storage level in battery; α/β maximum charging/discharging rate of battery; η^{c}/η^{d} battery charging/discharging efficiency. Parameters: dem^{(t,h)} demand of house h in time step t; res^{(t,h)} renewable energy production of house h in time step t; \\widetilde{res}^{(t,h,s)} renewable energy production of house h in time step t and scenario s; δ^{(t,h,s)} deviations in production of house h in time step t and scenario s; π_{s} probability of occurrence of renewable scenario s; p_{DA}^{(t)} price of electricity from the grid in the day-ahead market in time step t; p_{ID}^{(t,s)} price of electricity from the grid in the intraday market in time step t and scenario s; p_{F}^{(t)} price of electricity fed into the grid in time step t; p_{P2P}^{(t)} price of electricity in the local market in time step t. Variables: C_{DA}^{(t,h)} day-ahead charge of battery of house h in time step t; C_{ID}^{(t,h,s)} intraday charge of battery of house h in time step t and scenario s; D_{DA}^{(t,h)} day-ahead discharge of battery of house h in time step t; D_{ID}^{(t,h,s)} intraday discharge of battery of house h in time step t and scenario s; F_{DA}^{(t,h)} day-ahead feed of house h in time step t; G_{DA}^{(t,h)} day-ahead grid consumption of house h in time step t; G_{ID}^{(t,h,s)} intraday grid consumption of house h in time step t and scenario s; I_{DA}^{(t,h)} day-ahead P2P electricity purchase of house h in time step t; I_{ID}^{(t,h,s)} intraday P2P electricity purchase of house h in time step t and scenario s; I_{p,ID}^{(t,h←p,s)} intraday P2P electricity purchase of house h from peer p in time step t and scenario s; P^{(t,h)} day-ahead planned electricity supply of house h in time step t; Q^{(t,h)} day-ahead demanded electricity quantity of house h in time step t; S^{(t,h,s)} energy storage level in battery of house h in time step t and scenario s; X_{DA}^{(t,h)} day-ahead P2P electricity sale of house h in time step t; X_{ID}^{(t,h,s)} intraday P2P electricity sale of house h in time step t and scenario s; X_{p,ID}^{(t,h→p,s)} intraday P2P electricity sale of house h from peer p in time step t and scenario s."},{"evidence_id":"v141-b-g02-e23","location":{"location_id":"src-3c39fd6f72-p07-c1r1__v141-a-M01-clearing","page":7,"printed_page":null,"section":null,"anchor_text":"168 J.M. Zepter, A. Lüth and P. Crespo del Granado et al. / account a transmission and conversion lo","equation_id":"Eqs. (8)-(9)","figure_id":null,"table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"formula"},"source_text":"The overall purchased quantity per house I^{(t,h,s)} is then specified by Eq. (8). I^{(t,h,s)} = \\sum_{p≠h} I_{p}^{(t,h←p,s)} \\qquad (8)"}],"field_notes":{"empty_E_reason":null,"empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-bidding","v141-a-M01-clearing","v141-a-M01-coordination","v141-a-M01-participation","v141-a-M01-pricing"],"extras":{"decision_anchor":"execution.energy_trade","graph_fact_supports":[[{"evidence_id":"v141-b-g03-E03","quote":"Whenever the production exceeds the demand, the community commits a bid to the day-ahead market which they need to fulfil (in all possible scenarios)."}],[{"evidence_id":"v141-b-g02-e08","quote":"It then acts automatically based on this information, i.e. it bids to or procures electricity from the wholesale market"}],[{"evidence_id":"v141-b-g02-e38","quote":"The Base case is defined as today’s electricity market under dynamic real-time pricing. It is not possible to directly trade with other peers, and no electricity storage possibilities are deployed within this case."}],[{"evidence_id":"v141-b-g02-e38","quote":"The BAT market introduces the possibility of battery storage. Direct trade between the peers is disabled."}],[{"evidence_id":"v141-b-g02-e38","quote":"The P2P market includes the direct P2P trade connection in the community."}],[{"evidence_id":"v141-b-g02-e38","quote":"The STEP market offers both battery storage and P2P trade options within the community."}],[{"evidence_id":"v141-b-g03-E02","quote":"All four cases we apply allow for the possibility of grid infeed to the day-ahead market at dynamic compensations."}],[{"evidence_id":"v141-b-g02-e10","quote":"We assume that infeed from the community into the intraday market is not allowed"}],[{"evidence_id":"v141-b-g02-e07","quote":"The source of electricity for infeed can only be DG or the residential battery"}],[{"evidence_id":"v141-b-g02-e12","quote":"In case of an inability to balance supply and demand with these two market features, the community can procure electricity at uncertain reserve prices in the intraday market."}],[{"evidence_id":"v141-b-g02-e24","quote":"The sold and purchased quantity can, thus, only stay within the community."}],[{"evidence_id":"v141-b-g02-e22","quote":"The direct trade takes into account a transmission and conversion loss \\psi^{P2P} of 7.6% (see [24])."}]],"C2_formalization":{"graph_sha256":"4961b88355bd0fdfcfb21a5d096c2ea97258bc446dd1abe8e66648a275df3e86","applicability":"formalized","reason":"Partial formalization is source-supported: Eq. (9) directly states the community-level P2P sale/purchase balance and is represented under execution.energy_trade using source-defined P2P sale X, P2P purchase I, and the P2P conversion/transmission factor psi^P2P. The remaining constraints in this rule are procedural permissions, prohibitions, or statements for which the supplied text does not provide a self-contained mathematical expression. The exact numeric value of psi^P2P remains unresolved because Table 1 calls it an efficiency factor while the text reports a 7.6% loss. B evidence remains unreviewed; no source audit or independent review is claimed.","bindings":[{"object_id":"v141-c-R009-x01","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"X^{(t,h,s)} is the P2P sale quantity executed inside the community and constrained by Eq. (9); it is bound to execution.energy_trade. No relevant frozen edge exists for this node-level P2P balance."},{"object_id":"v141-c-R009-x02","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"I^{(t,h,s)} is the P2P purchase quantity executed inside the community and constrained by Eq. (9); it is bound to execution.energy_trade. No relevant frozen edge exists for this node-level P2P balance."},{"object_id":"v141-c-R009-theta01","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"psi^P2P modifies direct P2P execution through conversion and transmission and appears in Eq. (9); it binds to execution.energy_trade."},{"object_id":"v141-c-R009-C001","node_ids":["bidding.supply","execution.energy_trade"],"edge_ids":["v141-c-R009-E001"],"rationale":"The day-ahead supply bid implies a scenario-robust fulfilment obligation. This is exactly the frozen E001 relation from bidding.supply to execution.energy_trade."},{"object_id":"v141-c-R009-C002","node_ids":["coordination.local_operator","execution.energy_trade"],"edge_ids":["v141-c-R009-E002"],"rationale":"STEP coordinates community information and automatically procures electricity in the wholesale market. This is represented by the frozen E002 link from coordination.local_operator to execution.energy_trade."},{"object_id":"v141-c-R009-C003","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"The Base-case prohibition on direct peer trading is a condition on the execution.energy_trade node; the frozen graph provides no additional edge for this case restriction."},{"object_id":"v141-c-R009-C004","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"The BAT-case prohibition on direct peer trading is a condition on the execution.energy_trade node; no extra frozen edge exists for this case restriction."},{"object_id":"v141-c-R009-C005","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"The P2P-case permission for direct P2P trade is scoped to the execution.energy_trade node; no extra frozen edge exists for this permission."},{"object_id":"v141-c-R009-C006","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"The STEP-case permission for P2P trade is scoped to the execution.energy_trade node; no extra frozen edge exists for this permission."},{"object_id":"v141-c-R009-C007","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"The permission for grid infeed into the day-ahead market is an execution-side permission in this rule; it binds to execution.energy_trade."},{"object_id":"v141-c-R009-C008","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"The prohibition on infeed into the intraday market is an execution-side restriction in this rule; it binds to execution.energy_trade."},{"object_id":"v141-c-R009-C009","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"The source restriction on electricity for grid infeed is an execution-side condition; it binds to execution.energy_trade."},{"object_id":"v141-c-R009-C010","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"The conditional intraday-market procurement fallback is an execution-side procurement option; it binds to execution.energy_trade."},{"object_id":"v141-c-R009-C011","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"Eq. (9) is the community-level P2P sale/purchase balance. It executes P2P trade within the community and is represented by execution.energy_trade; the frozen graph has no separate clearing or counterparty edge for this equation."},{"object_id":"v141-c-R009-C012","node_ids":["execution.energy_trade"],"edge_ids":[],"rationale":"The stated 7.6% transmission and conversion loss modifies direct P2P execution; it binds to execution.energy_trade and to the separately declared psi^P2P parameter."}],"revision_requests":["Source clarification is needed for C012 and psi^P2P: Table 1 defines psi^P2P as an efficiency factor, while v141-b-g02-e22 reports a 7.6% transmission and conversion loss. The supplied text does not explicitly state the numeric coefficient used in Eq. (9), so C012 remains not_formalized and psi^P2P is represented symbolically."]}},"quarantined_references":[]}});
